function solution(rows, minSalary) {
  const out = {};
  for (const r of rows || []) {
    if (r && typeof r.salary === 'number' && r.salary >= minSalary) {
      out[r.department] = (out[r.department] || 0) + 1;
    }
  }
  return out;
}

